"use strict";
Object.defineProperty(exports, "__esModule", { value: true });
const LOCAL_ENVIRONMENT = {
    FORGE_LOCAL_STORAGE: '1',
    FORGE_LOCAL_KVS_URL: 'http://127.0.0.1:18090',
    FORGE_LOCAL_STORAGE_APP_ID: 'local-app',
    FORGE_LOCAL_STORAGE_ENVIRONMENT_ID: 'local-environment',
    FORGE_LOCAL_STORAGE_INSTALLATION_ID: 'local-installation'
};
describe('@forge/kvs local-storage routing', () => {
    beforeEach(() => {
        jest.resetModules();
        Object.assign(process.env, LOCAL_ENVIRONMENT);
        delete global.__forge_runtime__;
        global.__forge_fetch__ = jest.fn().mockRejectedValue(new Error('hosted storage was called'));
        global.__forge_local_fetch__ = jest.fn().mockResolvedValue(new Response('', { status: 200 }));
    });
    afterEach(() => {
        jest.dontMock('../storage-api');
        for (const key of Object.keys(LOCAL_ENVIRONMENT))
            delete process.env[key];
        delete global.__forge_runtime__;
        delete global.__forge_fetch__;
        delete global.__forge_local_fetch__;
    });
    it.each(['http://127.0.0.1:18090', 'http://127.0.0.1:18090/'])('routes ordinary SDK operations through local endpoint %s with deterministic namespace headers', async (baseUrl) => {
        process.env.FORGE_LOCAL_KVS_URL = baseUrl;
        const { kvs } = jest.requireActual('../index');
        await kvs.set('key', { value: true });
        expect(global.__forge_local_fetch__).toHaveBeenCalledWith(new URL('http://127.0.0.1:18090/api/v1/set'), expect.objectContaining({
            method: 'POST',
            headers: expect.objectContaining({
                'x-forge-app-id': 'local-app',
                'x-forge-environment-id': 'local-environment',
                'x-forge-installation-id': 'local-installation'
            })
        }));
        expect(global.__forge_fetch__).not.toHaveBeenCalled();
    });
    it.each([
        ['incomplete namespace', 'local namespace is incomplete'],
        ['non-loopback endpoint', 'must be http://127.0.0.1:18090'],
        ['missing bridge', 'requires the tunnel local-fetch bridge']
    ])('imports unrelated exports with %s and rejects the first KVS request asynchronously', async (condition, message) => {
        if (condition === 'incomplete namespace')
            delete process.env.FORGE_LOCAL_STORAGE_INSTALLATION_ID;
        if (condition === 'non-loopback endpoint')
            process.env.FORGE_LOCAL_KVS_URL = 'http://example.com:18090';
        const localFetch = global.__forge_local_fetch__;
        if (condition === 'missing bridge')
            delete global.__forge_local_fetch__;
        let api;
        expect(() => {
            api = jest.requireActual('../index');
        }).not.toThrow();
        expect(api.WhereConditions).toBeDefined();
        expect(api.Filter).toBeDefined();
        expect(api.ForgeKvsAPIError).toBeDefined();
        const request = api.kvs.set('key', { value: true });
        expect(request).toBeInstanceOf(Promise);
        await expect(request).rejects.toThrow(message);
        await expect(request).rejects.toBeInstanceOf(api.ForgeKvsError);
        await expect(request).rejects.toHaveProperty('packageVersion', new api.ForgeKvsError('fixture').packageVersion);
        expect(localFetch).not.toHaveBeenCalled();
        expect(global.__forge_fetch__).not.toHaveBeenCalled();
    });
    it('uses local configuration updated after import, including the namespace and bridge', async () => {
        const originalBridge = global.__forge_local_fetch__;
        const { kvs } = jest.requireActual('../index');
        const replacementBridge = jest.fn().mockResolvedValue(new Response('', { status: 200 }));
        Object.assign(process.env, {
            FORGE_LOCAL_KVS_URL: 'http://127.0.0.1:18090/',
            FORGE_LOCAL_STORAGE_APP_ID: 'updated-app',
            FORGE_LOCAL_STORAGE_ENVIRONMENT_ID: 'updated-environment',
            FORGE_LOCAL_STORAGE_INSTALLATION_ID: 'updated-installation'
        });
        global.__forge_local_fetch__ = replacementBridge;
        await kvs.set('key', { value: true });
        expect(replacementBridge).toHaveBeenCalledWith(new URL('http://127.0.0.1:18090/api/v1/set'), expect.objectContaining({
            headers: expect.objectContaining({
                'x-forge-app-id': 'updated-app',
                'x-forge-environment-id': 'updated-environment',
                'x-forge-installation-id': 'updated-installation'
            })
        }));
        expect(originalBridge).not.toHaveBeenCalled();
        expect(global.__forge_fetch__).not.toHaveBeenCalled();
    });
    it('enables local routing after import instead of retaining the hosted client', async () => {
        process.env.FORGE_LOCAL_STORAGE = '0';
        const { kvs } = jest.requireActual('../index');
        process.env.FORGE_LOCAL_STORAGE = '1';
        await kvs.set('key', { value: true });
        expect(global.__forge_local_fetch__).toHaveBeenCalledTimes(1);
        expect(global.__forge_fetch__).not.toHaveBeenCalled();
    });
    it('revalidates local configuration changed after import before fetching', async () => {
        const { kvs } = jest.requireActual('../index');
        delete process.env.FORGE_LOCAL_STORAGE_INSTALLATION_ID;
        await expect(kvs.set('key', { value: true })).rejects.toThrow('local namespace is incomplete');
        expect(global.__forge_local_fetch__).not.toHaveBeenCalled();
        expect(global.__forge_fetch__).not.toHaveBeenCalled();
    });
    it('preserves the generic hosted route when local storage is disabled', async () => {
        process.env.FORGE_LOCAL_STORAGE = '0';
        global.__forge_fetch__ = jest.fn().mockResolvedValue(new Response('', { status: 200 }));
        const { kvs } = jest.requireActual('../index');
        await kvs.set('key', { value: true });
        expect(global.__forge_fetch__).toHaveBeenCalledWith({ type: 'kvs', provider: 'app', remote: 'kvs' }, '/api/v1/set', expect.objectContaining({ method: 'POST' }));
        expect(global.__forge_local_fetch__).not.toHaveBeenCalled();
    });
    it('preserves hosted transport errors when local storage is disabled', async () => {
        process.env.FORGE_LOCAL_STORAGE = '0';
        const failure = new Error('hosted transport failed');
        const hostedFetch = jest.fn().mockRejectedValue(failure);
        Object.assign(global, { __forge_fetch__: hostedFetch });
        const { kvs } = jest.requireActual('../index');
        await expect(kvs.set('key', { value: true })).rejects.toBe(failure);
        expect(hostedFetch).toHaveBeenCalledTimes(1);
    });
    it('preserves local bridge transport errors without wrapping them', async () => {
        const failure = new TypeError('local bridge transport failed');
        const localFetch = jest.fn().mockRejectedValue(failure);
        Object.assign(global, { __forge_local_fetch__: localFetch });
        const { kvs } = jest.requireActual('../index');
        await expect(kvs.set('key', { value: true })).rejects.toBe(failure);
        expect(localFetch).toHaveBeenCalledTimes(1);
    });
    it('preserves hosted runtime routing and authentication headers when local storage is disabled', async () => {
        process.env.FORGE_LOCAL_STORAGE = '0';
        global.__forge_runtime__ = {
            kvs: { url: 'https://synthetic-kvs', host: 'synthetic-kvs' },
            proxy: { token: 'synthetic-token' },
            tracing: { traceId: 'synthetic-trace', spanId: 'synthetic-span' }
        };
        global.__forge_fetch__ = jest.fn().mockResolvedValue(new Response('', { status: 200 }));
        const { kvs } = jest.requireActual('../index');
        await kvs.set('key', { value: true });
        expect(global.__forge_fetch__).toHaveBeenCalledWith({ type: 'kvs' }, '/api/v1/set', expect.objectContaining({
            method: 'POST',
            headers: expect.objectContaining({
                Authorization: 'Bearer synthetic-token',
                Host: 'synthetic-kvs',
                'x-b3-traceid': 'synthetic-trace',
                'x-b3-spanid': 'synthetic-span'
            })
        }));
        expect(global.__forge_local_fetch__).not.toHaveBeenCalled();
    });
    it.each([
        'http://user:password@127.0.0.1:18090',
        'http://127.0.0.1:18090/?query=value',
        'http://127.0.0.1:18090/#fragment',
        'http://127.0.0.1:18090/not-root'
    ])('rejects noncanonical configured local KVS endpoint %s', async (baseUrl) => {
        process.env.FORGE_LOCAL_KVS_URL = baseUrl;
        const { kvs } = jest.requireActual('../index');
        await expect(kvs.set('key', { value: true })).rejects.toThrow('Forge local KVS endpoint must be http://127.0.0.1:18090.');
        expect(global.__forge_local_fetch__).not.toHaveBeenCalled();
        expect(global.__forge_fetch__).not.toHaveBeenCalled();
    });
    it.each([
        'http://example.com/api/v1/set',
        '//example.com/api/v1/set',
        'http://127.0.0.1:18091/api/v1/execute',
        '//127.0.0.1:18091/api/v1/execute'
    ])('blocks a resolved KVS request outside its emulator: %s', async (requestPath) => {
        let localClient;
        jest.doMock('../storage-api', () => ({
            StorageApi: jest.fn().mockImplementation((client) => {
                localClient = client;
            })
        }));
        const { ForgeKvsError } = jest.requireActual('../index');
        const request = localClient(requestPath);
        await expect(request).rejects.toThrow('Forge local KVS request must target http://127.0.0.1:18090.');
        await expect(request).rejects.toBeInstanceOf(ForgeKvsError);
        expect(global.__forge_local_fetch__).not.toHaveBeenCalled();
        expect(global.__forge_fetch__).not.toHaveBeenCalled();
    });
});
